_DIM_NUM = r"\d+(?:\.\d+)?(?:\s+\d+/\d+)?|\d+/\d+"
DIMENSIONS_TEXT = re.compile(rf"({_DIM_NUM})\s*(?:\"|in)?\s*[xX\u00d7]\s*({_DIM_NUM})")


def _dim_value(text):
    total = 0.0
    for part in text.split():
        if "/" in part:
            num, den = part.split("/")
            total += float(num) / float(den) if float(den) else 0.0
        else:
            total += float(part)
    return total


def parse_dimensions(text):
    m = DIMENSIONS_TEXT.search(text or "")
    if not m:
        return None
    a, b = _dim_value(m.group(1)), _dim_value(m.group(2))
    return max(a, b) / min(a, b) if a and b else None


def set_aspects(apps, schema_editor):
    """Existing aspects were entered by hand: mark them manual. Frames without one
    get it computed from Image dimension, falling back to Rabbet size."""
    Frame = apps.get_model("gallery", "Frame")
    AspectRatio = apps.get_model("gallery", "AspectRatio")
    ratios = list(AspectRatio.objects.all())
    Frame.objects.exclude(aspect=None).update(aspect_manual=True)
    for frame in Frame.objects.filter(aspect=None):
        value = parse_dimensions(frame.image_dimension) or parse_dimensions(frame.rabbet_size)
        if value and ratios:
            frame.aspect = min(ratios, key=lambda r: abs(math.log(value / float(r.ratio))))
            frame.save(update_fields=["aspect"])


